function Achievements(){return <section className="hub"><Crumb>Achievements</Crumb><p className="eyebrow">COMPLETION BOARD</p><h1>All 28 How to Fish<br/><i>Game Achievements</i></h1><p className="standfirst">A compact achievement overview for completion-minded crews. Use it alongside your creature checklist and boss board.</p><ol className="achievement-list">{achievements.map((a,i)=><li key={a}><span>{String(i+1).padStart(2,'0')}</span>{a}</li>)}</ol></section>}
