export function App({initialPath}:{initialPath?:string}){const path=initialPath??(typeof window==='undefined'?'/':window.location.pathname.replace(/\/$/,'')||'/');const Page=({'/':Home,'/beginner-guide':Beginner,'/creatures':Creatures,'/bosses':Bosses,'/locations':Locations,'/locations/lighthouse':LighthouseGuide,'/lures':Lures,'/bosses/spider-crab':SpiderCrab,'/achievements':Achievements}[path]||NotFound);return <><Meta path={path}/><Header/><main><Page/></main><Footer/></>};
